    "Monitor weather forecasts and preserve soil moisture through mulching.": "मौसम के पूर्वानुमान पर नज़र रखें और मल्चिंग के माध्यम से मिट्टी की नमी बनाए रखें।",
    "Protect young seedling shoots from cutworms and maintain adequate weed control.": "अंकुरित छोटे पौधों को कीड़ों से बचाएं और उचित खरपतवार नियंत्रण रखें।",
    "Watch closely for sucking pests and flower drop symptoms.": "रस चूसने वाले कीटों और फूलों के गिरने के लक्षणों पर कड़ी नज़र रखें।",
    "Inspect developing fruits for borer attacks and fungal spots.": "बढ़ते फलों में फल छेदक कीटों और फफूंद धब्बों की जांच करें।",
    "Apply nitrogen-rich fertilizer to support vigorous leaf and stem development.": "पत्तियों और तने के अच्छे विकास के लिए नाइट्रोजन युक्त उर्वरक डालें।",
    "Boost phosphorus and potassium levels to promote strong root and flower development.": "मजबूत जड़ों और फूलों के विकास को बढ़ावा देने के लिए फास्फोरस और पोटेशियम की मात्रा बढ़ाएं।",
    "Ensure potassium sufficiency to aid grain filling and fruit weight.": "दाने भरने और फल के वजन में सुधार के लिए पोटेशियम की पर्याप्त मात्रा सुनिश्चित करें।",
