    "Ready to Analyze Crop Disease": "ಬೆಳೆ ರೋಗ ವಿಶ್ಲೇಷಣೆಗೆ ಸಿದ್ಧ",
    "Select or capture a clear photo of an affected leaf to identify possible diseases, view symptoms, and receive AI treatment recommendations.": "ಸಾಧ್ಯವಿರುವ ರೋಗಗಳನ್ನು ಗುರುತಿಸಲು, ಲಕ್ಷಣಗಳನ್ನು ವೀಕ್ಷಿಸಲು ಮತ್ತು ಎಐ ಚಿಕಿತ್ಸಾ ಶಿಫಾರಸುಗಳನ್ನು ಪಡೆಯಲು ಬಾಧಿತ ಎಲೆಯ ಸ್ಪಷ್ಟ ಫೋಟೋವನ್ನು ಆಯ್ಕೆಮಾಡಿ ಅಥವಾ ತೆಗೆಯಿರಿ.",
