    "Check drip emitters and soil moisture levels for optimal water delivery.": "മികച്ച ജലസേചനത്തിനായി തുള്ളി നന ഉപകരണങ്ങളും മണ്ണിലെ ഈർപ്പവും പരിശോധിക്കുക.",
    "Inspect sprinkler nozzles and schedule watering during early morning hours.": "സ്പ്രിംഗ്ളർ നോസിലുകൾ പരിശോധിച്ച് അതിരാവിലെ നനയ്ക്കാൻ സമയം നിശ്ചയിക്കുക.",
    "Monitor weather forecasts and preserve soil moisture through mulching.": "കാലാവസ്ഥാ പ്രവചനം നിരീക്ഷിച്ച് മൾച്ചിംഗ് വഴി മണ്ണിലെ ഈർപ്പം നിലനിർത്തുക.",
    "Protect young seedling shoots from cutworms and maintain adequate weed control.": "ഇളം തൈകളെ കീടങ്ങളിൽ നിന്ന് സംരക്ഷിച്ച് കൃത്യമായ കളനിയന്ത്രണം ഉറപ്പാക്കുക.",
    "Watch closely for sucking pests and flower drop symptoms.": "നീരൂറ്റിക്കുടിക്കുന്ന കീടങ്ങളെയും പൂപൊഴിച്ചിൽ ലക്ഷണങ്ങളെയും ശ്രദ്ധിക്കുക.",
    "Inspect developing fruits for borer attacks and fungal spots.": "വളരുന്ന കായ്കളിൽ തണ്ട് തുരപ്പൻ ബാധയും ഫംഗസ് പാടുകളും പരിശോധിക്കുക.",
