    "Boost phosphorus and potassium levels to promote strong root and flower development.": "വേരുകളുടെയും പൂക്കളുടെയും വളർച്ചയ്ക്ക് ഫോസ്ഫറസ്, പൊട്ടാസ്യം അളവ് കൂട്ടുക.",
