    "Go to the Market Prices page, select your state, district, and crop to view current Mandi rates.": "હાલના માર્કેટ યાર્ડના ભાવ જોવા માટે માર્કેટ પ્રાઈસિસ પેજ પર જાઓ, તમારું રાજ્ય, જિલ્લો અને પાક પસંદ કરો.",
    "How do I use Crop Disease Detection?": "હું પાક રોગ નિદાનનો ઉપયોગ કેવી રીતે કરું?",
    "Go to Disease Detection, upload or snap a photo of the affected plant leaf, and receive AI diagnostic insights.": "ડિસીઝ ડિટેક્શન પર જાઓ, અસરગ્રસ્ત છોડના પાંદડાનો ફોટો અપલોડ કરો અથવા પાડો અને AI નિદાન મેળવો.",
    "How do I get personalized crop recommendations?": "મને વ્યક્તિગત પાક ભલામણો કેવી રીતે મળશે?",
    "Complete your Farm Profile with crop and location details to receive tailored advisory and weather alerts.": "ચોક્કસ સલાહ અને હવામાન એલર્ટ મેળવવા માટે પાક અને સ્થાનની વિગતો સાથે તમારી ફાર્મ પ્રોફાઇલ પૂર્ણ કરો.",
    "How do I change notification preferences?": "હું નોટિફિકેશન પસંદગીઓ કેવી રીતે બદલું?",
    "Go to Settings, scroll to Notification Preferences, and toggle weather, market, or crop advisory alerts.": "સેટિંગ્સમાં જાઓ, નોટિફિકેશન પ્રેફરન્સિસ પર સ્ક્ર્રોલ કરો এবং હવામાન, બજાર અથવા પાક સલાહ એલર્ટ ચાલુ/બંધ કરો.",
    "How do I change the application theme?": "હું એપ્લિકેશન થીમ કેવી રીતે બદલું?",
    "In Settings under Themes, select Fresh Green, Sky Blue, Warm Earth, or Dark Night mode.": "થીમ્સ હેઠળ સેટિંગ્સમાં, ફ્રેશ ગ્રીન, સ્કાય બ્લુ, વૉર્મ અર્થ અથવા ડાર્ક નાઇટ મોડ પસંદ કરો.",
    "How do I update my farm information?": "હું મારા ખેતરની માહિતી કેવી રીતે અપડેટ કરું?",
    "Navigate to My Farm or Profile page to update your crop type, farm area, soil type, and sowing dates.": "તમારા પાકનો પ્રકાર, ખેતરનો વિસ્તાર, જમીનનો પ્રકાર અને વાવણીની તારીખો અપડેટ કરવા માટે માય ફાર્મ અથવા પ્રોફાઇલ પેજ પર જાઓ.",
    "How do I change accessibility settings?": "હું એક્સેસિબિલિટી સેટિંગ્સ કેવી રીતે બદલું?",
    "In Settings under Accessibility Preferences, adjust font size, enable high contrast, or reduce motion.": "એક્સેસિબિલિટી પ્રેફરન્સિસ હેઠળના સેટિંગ્સમાં, ફોન્ટ સાઈઝ સરખી કરો, હાઈ કોન્ટ્રાસ્ટ ચાલુ કરો અથવા મોશન ઘટાડો.",
    "My Farm": "મારું ખેતર",
    "Manage crop and farming information.": "પાક અને ખેતીની માહિતીનું સંચાલન કરો.",
    "Ask agricultural questions using text or voice.": "લખાણ અથવા અવાજનો ઉપયોગ કરીને કૃષિ પ્રશ્નો પૂછો.",
    "Upload a crop image to check possible diseases.": "સંભવિત રોગો ચકાસવા માટે પાકની છબી અપલોડ કરો.",
    "Check current crop market prices.": "હાલના પાક બજાર ભાવ ચકાસો.",
    "View weather information for your location.": "તમારા સ્થાન માટે હવામાન માહિતી જુઓ.",
    "Government Schemes": "સરકારી યોજનાઓ",
    "Explore agricultural government schemes.": "કૃષિ સરકારી યોજનાઓ વિશે જાણો.",
    "Microphone not working": "માઇક્રોફોન કામ કરતું નથી",
    "Ensure your browser has permission to access the microphone. Check browser site settings and reload.": "તમારા બ્રાઉઝર પાસે માઇક્રોફોનનો ઉપયોગ કરવાની પરવાનગી છે તેની ખાતરી કરો. બ્રાઉઝર સાઇટ સેટિંગ્સ ચકાસો અને રીલોડ કરો.",
    "Language not changing": "ભાષા બદલાતી નથી",
    "Select your preferred language from the top navigation bar dropdown. The entire page will update instantly.": "ટોચના નેવિગેશન બાર ડ્રોપડાઉનમાંથી તમારી પસંદગીની ભાષા પસંદ કરો. આખું પેજ તરત જ અપડેટ થઈ જશે.",
    "Voice response not working": "અવાજ જવાબ કામ કરતો નથી",
    "Verify that your device audio is unmuted and voice output settings are enabled in Language & Voice Preferences.": "તમારા ઉપકરણનું ઓડિયો અનમ્યુટ છે અને ભાષા અને અવાજ પસંદગીઓમાં વૉઇસ આઉટપુટ સેટિંગ્સ ચાલુ છે તેની ખાતરી કરો.",
    "Disease image not uploading": "રોગની છબી અપલોડ થતી નથી",
    "Make sure your image is in JPG, PNG, or WEBP format and smaller than 10 MB in size.": "તમારી છબી JPG, PNG અથવા WEBP ફોર્મેટમાં છે અને તેની સાઈઝ 10 MB થી નાની છે તેની ખાતરી કરો.",
    "Market prices not loading": "બજાર ભાવ લોડ થતા નથી",
    "Check your network connection, re-select your state and district, and refresh the market prices page.": "તમારું નેટવર્ક કનેક્શન ચકાસો, તમારું રાજ્ય અને જિલ્લો ફરીથી પસંદ કરો અને બજાર ભાવ પેજ રીફ્રેશ કરો.",
