    "Chat greeting": "నమస్కారం! నేను మీ ఏఐ వ్యవసాయ సలహాదారుని. పంటలు, వ్యవసాయం, వాతావరణం, వ్యాధులు, మార్కెట్ సమాచారం లేదా ప్రభుత్వ పథకాల గురించి ఏదైనా అడగండి.",
    "Market Prices": "మార్కెట్ ధరలు", "Search today's mandi prices.": "నేటి మండీ ధరలను శోధించండి.", "Search Market Prices": "మార్కెట్ ధరలను శోధించండి", Commodity: "వస్తువు", "Select Commodity": "వస్తువును ఎంచుకోండి", "Select Commodity First": "ముందుగా వస్తువును ఎంచుకోండి", "Select State": "రాష్ట్రాన్ని ఎంచుకోండి", "Select State First": "ముందుగా రాష్ట్రాన్ని ఎంచుకోండి", "Select District": "జిల్లాను ఎంచుకోండి", Search: "శోధించండి", "Searching...": "శోధిస్తోంది...", "Please fill all fields.": "దయచేసి అన్ని వివరాలు పూరించండి.", "Unable to load market options.": "మార్కెట్ ఎంపికలను లోడ్ చేయలేకపోయాము.", "No market data found for this selection.": "ఈ ఎంపికకు మార్కెట్ డేటా లేదు.", "Unable to fetch market prices.": "మార్కెట్ ధరలను పొందలేకపోయాము.",
    "Weather Advisory": "వాతావరణ సలహా", "Check current weather and upcoming forecast for your farming location.": "మీ వ్యవసాయ స్థలానికి ప్రస్తుత వాతావరణం మరియు రాబోయే అంచనాను చూడండి.", "Select Location": "స్థలాన్ని ఎంచుకోండి", "Enter city name (e.g. Chennai)": "నగరం పేరు నమోదు చేయండి (ఉదా. చెన్నై)", "Check Weather": "వాతావరణం చూడండి", "Checking...": "తనిఖీ చేస్తోంది...", "Government Schemes": "ప్రభుత్వ పథకాలు", "Discover government schemes, subsidies, insurance and financial support available for farmers.": "రైతులకు అందుబాటులో ఉన్న ప్రభుత్వ పథకాలు, సబ్సిడీలు, బీమా మరియు ఆర్థిక సహాయాన్ని తెలుసుకోండి.", "Find Government Schemes": "ప్రభుత్వ పథకాలను కనుగొనండి", "Ask any question about agricultural government schemes.": "వ్యవసాయ ప్రభుత్వ పథకాల గురించి ఏదైనా అడగండి.", "Example: What schemes are available for small farmers?": "ఉదాహరణ: చిన్న రైతులకు ఏ పథకాలు అందుబాటులో ఉన్నాయి?", "Find Schemes": "పథకాలను కనుగొనండి", "Quick Searches": "త్వరిత శోధనలు", "Select a category to quickly discover relevant farmer schemes.": "సంబంధిత రైతు పథకాలను త్వరగా తెలుసుకోవడానికి వర్గాన్ని ఎంచుకోండి.", "Explore available schemes": "అందుబాటులో ఉన్న పథకాలను చూడండి", "Financial Assistance": "ఆర్థిక సహాయం", "Crop Insurance": "పంట బీమా", "Irrigation Support": "నీటిపారుదల సహాయం", "Farm Machinery": "వ్యవసాయ యంత్రాలు", "Small Farmers": "చిన్న రైతులు",
    "Financial Support": "ఆర్థిక మద్దతు", "Crop Protection": "పంట రక్షణ", "Farming Assistance": "వ్యవసాయ సహాయం", "Explore financial assistance and farmer support schemes available through government programs.": "ప్రభుత్వ కార్యక్రమాల ద్వారా అందుబాటులో ఉన్న ఆర్థిక సహాయం మరియు రైతు మద్దతు పథకాలను చూడండి.", "Find information about crop insurance and agricultural risk protection programs.": "పంట బీమా మరియు వ్యవసాయ ప్రమాద రక్షణ కార్యక్రమాల సమాచారం పొందండి.", "Ask about irrigation, machinery and other agricultural support programs.": "నీటిపారుదల, యంత్రాలు మరియు ఇతర వ్యవసాయ మద్దతు కార్యక్రమాల గురించి అడగండి.", "Important Information": "ముఖ్యమైన సమాచారం", "Scheme eligibility, benefits and application requirements may change. Verify important details through the relevant official government authority before applying.": "పథకం అర్హత, ప్రయోజనాలు మరియు దరఖాస్తు అవసరాలు మారవచ్చు. దరఖాస్తు చేయడానికి ముందు సంబంధిత ప్రభుత్వ అధికారుల ద్వారా వివరాలను ధృవీకరించండి.",
    "My Profile": "నా ప్రొఫైల్", "Manage your personal details and farming preferences.": "మీ వ్యక్తిగత వివరాలు మరియు వ్యవసాయ ప్రాధాన్యతలను నిర్వహించండి.", "Loading Profile...": "ప్రొఫైల్ లోడ్ అవుతోంది...", "Unnamed Farmer": "పేరు లేని రైతు", "Location not provided": "స్థలం అందుబాటులో లేదు", "Personal Information": "వ్యక్తిగత సమాచారం", "Farming Information": "వ్యవసాయ సమాచారం", "Full Name": "పూర్తి పేరు", Email: "ఇమెయిల్", "Phone Number": "ఫోన్ నంబర్", State: "రాష్ట్రం", District: "జిల్లా", City: "నగరం", "Farmer Type": "రైతు రకం", "Primary Crop": "ప్రధాన పంట", "Farm Size": "పొలం పరిమాణం", "Soil Type": "నేల రకం", Preferences: "ప్రాధాన్యతలు", "Preferred Language": "ఇష్టమైన భాష", Cancel: "రద్దు చేయండి", "Save Changes": "మార్పులు సేవ్ చేయండి", "Edit Profile": "ప్రొఫైల్ సవరించండి", "cannot be changed": "మార్చలేరు", "Enter value": "విలువ నమోదు చేయండి", "Not provided": "అందుబాటులో లేదు", "Profile Updated Successfully": "ప్రొఫైల్ విజయవంతంగా నవీకరించబడింది", "Profile Update Failed": "ప్రొఫైల్ నవీకరణ విఫలమైంది",
